/** Bind only actual same-loaded singular File or nominal/alias stored fields. The profile owns
 * whole-value validation; the host still owns finalization and retention. */
async function bindFileStagingCensus(loaded: LoadedCanonicalDescriptors,
  artifact: CompileArtifact): Promise<FileStagingCensus | undefined> {
  const schema = loaded.valueSchema;
  if (schema === undefined) {
    if (artifact.models?.some(model => model.fields.some(field => field.field.kind === 'nominal'))) {
      throw new Error('Stored nominal fields require their complete owning type and File census.');
    }
    return undefined;
  }
  const candidates = (artifact.models ?? []).flatMap(model => model.fields.flatMap(field => {
    if (field.field.kind === 'nominal') {
      if (field.valueType === undefined || schema === undefined) {
        throw new Error('Stored nominal fields require their complete owning type and File census.');
      }
      return [{ model: model.name as ModelName, field: field.name }];
    }
    if (field.field.kind !== 'other' || field.valueType === undefined || schema === undefined) return [];
    const type = parseTypeId(field.valueType);
    if (type.base.kind !== 'nominal' ||
        !Object.hasOwn(schema.contracts, type.base.path) &&
        !(schema.aliases !== undefined && Object.hasOwn(schema.aliases, type.base.path))) return [];
    return [{ model: model.name as ModelName, field: field.name }];
  }));
  if (candidates.length === 0) return undefined;
  const state = await loadProducerModule('@canlang/state', 'stored File census');
  const bind = requireProducerFn(state, 'bindFileReferenceProfile', 'stored File census') as
    typeof import('@canlang/state/ports/file-reference-profile').bindFileReferenceProfile;
  const occurrences = requireProducerFn(state, 'fileReferenceOccurrences', 'stored File census') as
    typeof import('@canlang/state/ports/file-reference-profile').fileReferenceOccurrences;
  const systemManagedTopLevelFields = requireProducerFn(state, 'systemManagedTopLevelFields', 'stored File census') as
    typeof import('@canlang/state/ports/file-reference-profile').systemManagedTopLevelFields;
  const systemManagedFields = systemManagedTopLevelFields();
  const authoredCandidates = candidates.filter(candidate => !systemManagedFields.has(candidate.field));
  if (authoredCandidates.length === 0) return undefined;
  const bound = { canonicalModels: loaded.models,
    artifactModels: new Map((artifact.models ?? []).map(model => [model.name as ModelName, model])),
    ...(loaded.valueTypes === undefined ? {} : { valueTypes: loaded.valueTypes }),
    valueSchema: schema };
  const fields = new Map<string, Map<string, ReturnType<typeof bind>>>();
  for (const candidate of authoredCandidates) {
    const profile = bind(bound, candidate.model, candidate.field);
    if (!profile.fileBearing) continue;
    let model = fields.get(candidate.model);
    if (model === undefined) { model = new Map(); fields.set(candidate.model, model); }
    model.set(candidate.field, profile);
  }
  return { fields, occurrences };
}
async function bindNativeScenarioStoredFiles(loaded: LoadedCanonicalDescriptors, artifact: CompileArtifact): Promise<void> {
  let bindProfile: typeof import('@canlang/state').bindFileReferenceProfile | undefined;
  const bound = { canonicalModels: loaded.models,
    artifactModels: new Map((artifact.models ?? []).map(model => [model.name as ModelName, model])),
    ...(loaded.valueTypes === undefined ? {} : { valueTypes: loaded.valueTypes }),
    ...(loaded.valueSchema === undefined ? {} : { valueSchema: loaded.valueSchema }) };
  for (const value of loaded.registry.values()) {
    const def = generatedScenarioDef({ def: value }), plan = def?.descriptor.result?.disclosure;
    if (def === undefined || plan === undefined) continue;
    const profiles = new Map<string, { readonly model: string; readonly field: string;
      readonly profile: import('@canlang/state').FileReferenceProfile }>();
    for (const returned of scenarioDisclosureReturns(plan)) for (const dependency of returned.dependencies) {
      const parsed = parseTypeId(dependency.type);
      const directFile = dependency.type === 'file' || dependency.type === 'file?' || dependency.type === 'file[]';
      const nominal = parsed.base.kind === 'nominal' && loaded.valueSchema !== undefined &&
        Object.hasOwn(loaded.valueSchema.contracts, parsed.base.path);
      if ((!directFile && !nominal) || profiles.has(dependency.id)) continue;
      if (bindProfile === undefined) {
        const state = await loadProducerModule('@canlang/state', 'stored nominal File census');
        bindProfile = requireProducerFn(state, 'bindFileReferenceProfile', 'stored nominal File census') as
          typeof import('@canlang/state').bindFileReferenceProfile;
      }
      const profile = bindProfile(bound, dependency.model, dependency.field);
      if (profile.type !== dependency.type) throw new AssemblyCorrespondenceError('Stored nominal dependency differs from its complete owning field type.');
      if (profile.fileBearing) profiles.set(dependency.id, Object.freeze({ model: dependency.model, field: dependency.field, profile }));
    }
    if (profiles.size !== 0) nativeScenarioStoredFileProfiles.set(def, profiles);
  }
}
