        const binding = localPolicyObject(raw, ['id', 'module', 'ownerPackage', 'model', 'kind', 'run']);
        const id = localPolicyMember(binding, 'id'), model = localPolicyMember(binding, 'model');
        const run = localPolicyMember(binding, 'run');
